const msgs = $input.first().json.messages || [];
const esHumano = (m) => m.human !== undefined || m.type === 'human';
const texto = (m) => m.human ?? m.ai ?? m.content ?? JSON.stringify(m);
const total_usuario = msgs.filter(esHumano).length;
const historial = msgs
  .map(m => (esHumano(m) ? 'Usuario: ' : 'Agente: ') + texto(m))
  .join('\n');
return [{ json: { total_usuario, historial } }];

